components/layout/v5/V5.module.css.suffix:
/* Only category/404 recovery expanded links; headline links and card paint stay intact. */
@media (max-width:1023px) { :global(section:is([aria-labelledby="category-articles"],[aria-labelledby="not-found-latest"])) .articleCardTitle a::after { right:calc(80px - var(--v5-gutter)); } }
@media (min-width:1024px) { :global(#v5-blog-scope) .articleCardTitle a::after, :global(section[aria-labelledby="not-found-latest"]) .articleCardTitle a::after { right:calc(248px - var(--v5-gutter)); } }

components/layout/v5/V5Tool.module.css.suffix:
/* Desktop clearance is local to the two measured paragraphs, not the reading/form columns. */
@media (min-width:1024px) {
  .legalBody :global(#privacy-collect) > p:nth-of-type(3) { padding-right:clamp(48px, calc(764px - 50vw), calc(248px - var(--v5-gutter))); }
  :global(#fhc-calculator) .asideCard > p:last-child { padding-right:calc(224px - var(--v5-gutter)); }
}

features/blog/v5/V5Blog.module.css.suffix:
/* Clearance for the category list heading and the desktop featured-card excerpt only. */
@media (max-width:479px) { .categoryHero ~ section :global(#category-articles) { display:block; box-sizing:border-box; padding-right:60px; } }
@media (min-width:1024px) { .featuredLead > div > p, .featuredLead > div > div:has(button) { padding-right:calc(216px - var(--v5-gutter, 80px)); } }

features/investment-allocation/Investmen.suffix:
/* Reserve only the native mode-choice controls beside the fixed LINE dock. */
@media (max-width:1023px) { .modeGrid { padding-right:calc(80px - var(--v5-gutter, 20px)); box-sizing:border-box; } }
@media (max-width:479px) { :global(main:has(#aia-fund-hero-title)) .modeLead { padding-right:60px; } }
@media (min-width:1024px) { :global(main:has(#aia-fund-hero-title)) .modeGrid { padding-right:calc(248px - var(--v5-gutter, 80px)); box-sizing:border-box; } }

features/money-story/MoneyStory.module.c.suffix:
/* Owner-approved dock clearance: selection controls only; gameplay geometry is unchanged. */
@media (max-width:479px) {
  .start > .characterPicker { display:grid; grid-template-columns:minmax(0,1fr); margin:22px 60px 0 0; padding:0 0 10px; overflow:visible; scroll-snap-type:none; }
  .start > .characterPicker > .characterPickCard { flex:none; width:100%; }
  .start > .mobileSwipeHint { display:none!important; }
}
@media (min-width:681px) and (max-width:1023px) { .start > .characterPicker { margin-right:calc(52px - var(--v5-gutter, 32px)); } }
@media (min-width:1024px) { .start > .characterPicker { margin-left:auto; margin-right:calc(224px - var(--v5-gutter, 80px)); } }

@media (min-width:480px) and (max-width:680px) { .start > .startActions { padding-right:44px; } }

features/tools-hub/ToolsHub.module.css.suffix:
/* Shorten the transparent expanded hit area beside LINE without changing the tool card. */
@media (max-width:1023px) { .card h2 a::after { right:calc(80px - var(--v5-gutter)); } }
@media (max-width:479px) { .card:has(h2 a[href="/tools/financial-health-check/"]) > p { padding-right:40px; } }
@media (min-width:1024px) { .card h2 a::after { right:calc(248px - var(--v5-gutter)); } }
